import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import {
  createBlindMapping,
  finalizeScores,
  revealMapping,
  writeBlindPackage,
  writePrivateMapping
} from '../src/blind.mjs';
import { loadFixtureInput } from '../src/fixture.mjs';
import { readJson, writeJsonAtomic } from '../src/util.mjs';
import { completeScore, syntheticWorkspace, validStubResponses } from './helpers.mjs';

test('blind packages hide identity and reveal only after sealed complete scoring', async t => {
  const workspace = await syntheticWorkspace();
  const runDirectory = await fs.mkdtemp(path.join(os.tmpdir(), 'anyways-blind-test-'));
  t.after(async () => {
    await workspace.cleanup();
    await fs.rm(runDirectory, { recursive: true, force: true });
  });
  const mapping = createBlindMapping({
    runId: 'synthetic-run',
    fixtureIds: ['synthetic-fixture'],
    modelIds: ['secret-model-tag']
  });
  const mappingFile = await writePrivateMapping(runDirectory, mapping);
  const mode = (await fs.stat(mappingFile)).mode & 0o777;
  assert.equal(mode, 0o600);
  const input = await loadFixtureInput(workspace.fixture);
  const outputs = validStubResponses();
  const packaged = await writeBlindPackage({
    runDirectory,
    mapping,
    fixture: input,
    modelId: 'secret-model-tag',
    identityValues: ['qwen3:14b', 'ollama'],
    outputs: { ...outputs, reviewer: { ...outputs.reviewer, summary: 'Generated by qwen3:14b through ollama at /Volumes/secret/path.' } },
    evaluations: { draft: { findings: [], timing: { wall_ms: 9 }, model: 'secret-model-tag' } }
  });
  const packageText = await fs.readFile(path.join(packaged.packageDirectory, 'review-package.json'), 'utf8');
  assert.doesNotMatch(packageText, /secret-model-tag|qwen3:14b|ollama|\/Volumes\/secret|wall_ms|REFERENCE_SENTINEL|adapter|digest|provider/i);
  await assert.rejects(() => revealMapping({ runDirectory }), /finalized score checksums do not exist/);
  const score = completeScore(await readJson(packaged.scoreFile));
  await writeJsonAtomic(packaged.scoreFile, score);
  const humanSchema = await readJson(new URL('../schemas/human-score.schema.json', import.meta.url));
  await finalizeScores({ runDirectory, humanScoreSchema: humanSchema });
  const reveal = await revealMapping({ runDirectory });
  assert.equal(reveal.entries[0].model_id, 'secret-model-tag');
  score.comments = 'Changed after finalization.';
  await writeJsonAtomic(packaged.scoreFile, score);
  await assert.rejects(() => revealMapping({ runDirectory }), /score checksum changed/);
});
